Input: Root node T of (sub-) tree T for re-building, Re-build Switch SW
1 Function Rebalance(T,SW)
2    if ViolateCriterion(T) then
3    if T.treesize < Nmax or Not SW then
4    | Rebuild(T)
5    else
6    | ThreadSpawn(ParRebuild,T)
7    end
8    end
9 End Function
10
11 Function ParRebuild(T)
12    LockUpdates(T);
13    V ← Flatten(T);
14    Unlock(T);
15    T' ← Build(V);
16    foreach op in OperationLogger do
17    IncrementalUpdates(T',op,false)
18    end
19    Ttemp ← T;
20    LockAll(T);
21    T ← T';
22    Unlock(T);
23    Free(Ttemp);
24 End Function

